class Solution {
  public boolean isValidPalindrome(String s, int k) {
    int n = s.length();
    int[][] dp = new int[n][n]; // longest palindromic subsequence of s[i..j]
    for (int i = n - 1; i >= 0; i--) {
      dp[i][i] = 1;
      for (int j = i + 1; j < n; j++)
        dp[i][j] = s.charAt(i) == s.charAt(j) ? dp[i + 1][j - 1] + 2 : Math.max(dp[i + 1][j], dp[i][j - 1]);
    }
    return n - dp[0][n - 1] <= k;
  }
}
